"""Regression coverage for context preparation of Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('value', [False, True])
def test_faker_decider_resolves_provider_arguments(value):
    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pybool',
                truth_probability=factory.LazyFunction(lambda: 100 if value else 0),
                locale='en_US',
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert SampleFactory()['result'] == ('yes' if value else 'no')


@pytest.mark.parametrize('value', [False, True])
def test_nested_maybe_decider(value):
    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: value), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert SampleFactory()['result'] == ('yes' if value else 'no')
